"use client"

import * as React from "react"
import * as TogglePrimitive from "@radix-ui/react-toggle"

import { cn } from "@/lib/utils"

type ToggleProps = React.ComponentProps<typeof TogglePrimitive.Root> & {
  /** Pins a state for documentation ("hover"); set on the root. */
  "data-force"?: string
}

/** A word you can hold down. Held, it wears the fermata: an arc over the word and a dot inside it. */
function Toggle({ className, ...props }: ToggleProps) {
  return <TogglePrimitive.Root data-slot="toggle" className={cn("db-toggle", className)} {...props} />
}

export { Toggle, type ToggleProps }

@layer components {
  /* ── db-toggle ── a word you can hold down; held, it wears the fermata */
  .db-toggle {
    --pad: 0px;
    position: relative; appearance: none; border: 0; background: none; margin: 0; padding: 0.8em 0 0;
    font: inherit; color: var(--db-graphite); cursor: pointer; -webkit-tap-highlight-color: transparent;
    transition: color var(--db-allegro), font-weight var(--db-andante) var(--db-exhale), font-stretch var(--db-andante) var(--db-exhale);
  }
  /* The sign for a note held longer than written: an arc over the word, a dot inside it. */
  .db-toggle::before, .db-toggle::after { content: ""; position: absolute; inset-inline-start: calc(50% + var(--pad) / 2); pointer-events: none; }
  .db-toggle::before {
    top: 0; width: 0.9em; height: 0.45em; margin-inline-start: -0.45em;
    border: var(--db-hairline) solid var(--db-rule-strong); border-bottom: 0; border-radius: 0.45em 0.45em 0 0;
    opacity: 0; scale: 1 0; transform-origin: 50% 100%;
    transition: scale var(--db-moderato) var(--db-exhale), opacity var(--db-allegro), border-color var(--db-allegro);
  }
  .db-toggle::after {
    top: calc(0.45em - 5px); width: 5px; height: 5px; margin-inline-start: -2.5px; border-radius: 50%;
    background: var(--db-ink); scale: 0; transition: scale var(--db-moderato) var(--db-spiccato);
  }
  .db-toggle:is(:hover, [data-force~="hover"]):not(:disabled) { color: var(--db-ink); }
  .db-toggle:is(:hover, [data-force~="hover"]):not(:disabled)::before { opacity: 1; scale: 1; }
  .db-toggle[data-state="on"] { color: var(--db-ink); }
  .db-toggle[data-state="on"]::before { opacity: 1; scale: 1; border-color: var(--db-ink); border-width: var(--db-stroke); }
  .db-toggle[data-state="on"]::after { scale: 1; transition-delay: 140ms; } /* the arc rises, then the dot lands */
  .db-toggle:disabled { color: var(--db-pencil); opacity: 0.55; cursor: not-allowed; }
}
